@startuml
class Calculation {
  +id: String
  +firstNumber: Number
  +secondNumber: Number
  +operation: String
  +result: Number
}
class CalculationService {
  +list(): Calculation
  +create(firstNumber: Number, secondNumber: Number, operation: String, result: Number): Calculation
  +update(id: String): Calculation
  +remove(id: String): void
}
class CalculationRepository {
  +list(): Calculation
  +findById(id: String): Calculation
  +create(value: Calculation): Calculation
  +update(id: String): Calculation
  +remove(id: String): void
}
CalculationService --> CalculationRepository : uses
CalculationRepository --> Calculation : persists
@enduml
